<?php
namespace App\Http\Middleware;
use Closure;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\{CcsRuleGuard,CcsHumanRules,CcsAdministration};
class CcsHumanRulesMiddleware{
public function handle(Request $r,Closure $next){
if(!in_array($r->method(),['POST','PUT','PATCH','DELETE'],true)||!in_array(class_basename($r->route()?->getControllerClass()??''),['CcsAdminController','CcsStockController','CcsBillingController','CcsWarrantyController','CcsClaimController','CcsTechnicianController'],true))return $next($r);
$rules=app(CcsHumanRules::class);$guard=app(CcsRuleGuard::class);$method=$r->route()?->getActionMethod();$action=$r->route()?->getName()??'';$raw=$r->except(['_token','rules_version','rules_submission']);ksort($raw);$hash=hash('sha256',json_encode($raw,JSON_UNESCAPED_UNICODE));$token=$r->input('rules_submission');$create=in_array($method,['saveCustomer','saveVehicle','saveJob','create','createInvoice','store','assign'],true);if($create)$r->validate(['rules_submission'=>'required|uuid']);
if($token&&($prior=DB::table('ccs_rule_submissions')->where('token',$token)->first()))return $this->replay($prior,$r,$action,$hash);
if($method==='createInvoice'&&$r->filled('initial_request_token')&&($invoice=DB::table('invoices')->where('rules_request_token',$r->input('initial_request_token'))->first())){if(!hash_equals((string)$invoice->rules_payload_hash,app(\App\Services\CcsInvoiceInput::class)->hash($r)))$rules->fail('rules','Invoice request token already used for different details.');return redirect()->route('ccs.invoices.show',$invoice->id);}
$guard->before($r);
return DB::transaction(function()use($r,$next,$guard,$rules,$action,$hash,$token){$rules->lock();if($token&&($prior=DB::table('ccs_rule_submissions')->where('token',$token)->first()))return $this->replay($prior,$r,$action,$hash);$target=$guard->target($r);$old=$target?(array)DB::table($target[0])->find($target[1]):null;if($target&&!hash_equals($guard->version($target),(string)$r->input('rules_version')))$rules->fail('rules','This record changed or the page is outdated. Reload and review before saving.');$guard->before($r,true);$response=$next($r);if($response->getStatusCode()<400){$guard->consume($r);if($target){$new=(array)DB::table($target[0])->find($target[1]);app(CcsAdministration::class)->audit($r->user()->id,'rules_record_changed',$target[0],$target[1],['before'=>$old,'after'=>$new,'reason'=>$r->input('rules_reason'),'completion_checks_confirmed'=>$r->boolean('rules_completion_check')]);}if($token&&$response->isRedirection())DB::table('ccs_rule_submissions')->insert(['token'=>$token,'user_id'=>$r->user()->id,'action'=>$action,'fingerprint'=>$hash,'location'=>$response->headers->get('Location'),'created_at'=>now(),'updated_at'=>now()]);}return $response;},3);
}
private function replay($prior,Request $r,string $action,string $hash){if((int)$prior->user_id!==(int)$r->user()->id||$prior->action!==$action||!hash_equals($prior->fingerprint,$hash))app(CcsHumanRules::class)->fail('rules','This save token was already used for different details. Reload.');return redirect($prior->location)->with('success','This action was already saved; no duplicate record was created.');}
}
